import numpy as np
from scipy import stats
from sklearn.cluster import SpectralClustering
from sklearn.metrics.pairwise import cosine_similarity

MAX_DRIVERS = 5

def design(feats):
    # Filter for significant features (p < 0.05) and remove near-duplicates
    sig_idx = []
    for i, fid in enumerate(feats.ids):
        if i < len(feats.ids):  # Ensure we don't go out of bounds
            try:
                t_stat, p_val = stats.ttest_ind(
                    feats.x[feats.y==1, feats.column(fid)], 
                    feats.x[feats.y==0, feats.column(fid)], 
                    equal_var=False
                )
                if p_val < 0.05:
                    sig_idx.append(i)
            except:
                continue

    # Identify correlated pairs
    corr_pairs = []
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]) >= 0.6:
                corr_pairs.append((fid1, fid2))

    # Build adjacency matrix from correlations
    adj = np.zeros((len(feats.ids), len(feats.ids)))
    for fid1, fid2 in corr_pairs:
        adj[feats.column(fid1), feats.column(fid2)] = 1
        adj[feats.column(fid2), feats.column(fid1)] = 1

    # Spectral clustering to find modules
    try:
        clustering = SpectralClustering(n_clusters=2, affinity='precomputed', random_state=0)
        labels = clustering.fit_predict(adj)

        # Find largest cluster
        unique_labels, counts = np.unique(labels, return_counts=True)
        main_cluster = unique_labels[np.argmax(counts)]
        module_ids = [feats.ids[i] for i in range(len(feats.ids)) if labels[i] == main_cluster]

        # Weighted score using mean differences
        loadings = {}
        for fid in module_ids:
            try:
                diff = np.mean(feats.x[feats.y==1, feats.column(fid)]) - np.mean(feats.x[feats.y==0, feats.column(fid)])
                loadings[fid] = diff
            except:
                continue

        # Drivers: top features by effect size (max 4 due to constraint)
        drivers = sorted(loadings.keys(), key=lambda x: abs(loadings[x]), reverse=True)[:min(MAX_DRIVERS-1, len(loadings))]

        # Return design
        return Design(
            drivers=tuple(drivers),
            columns=tuple(module_ids),
            products=(),
            loadings=loadings
        )
    except:
        # If clustering fails, return empty design
        return Design(
            drivers=(),
            columns=(),
            products=(),
            loadings={}
        )
